function e(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function money(float|int $v): string { return 'Rp '.number_format((float)$v,0,',','.'); }
function pct(float $v): string { return number_format($v,1,',','.').'%' ; }
function textLength(string $v): int { return function_exists('mb_strlen') ? mb_strlen($v,'UTF-8') : strlen($v); }
function textTail(string $v,int $n): string { return function_exists('mb_substr') ? mb_substr($v,-$n,null,'UTF-8') : substr($v,-$n); }
function jsonOut(array $data, int $status=200): never { http_response_code($status); header('Content-Type: application/json; charset=utf-8'); echo json_encode($data, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); exit; }
function csrf(): string { if(empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(24)); return $_SESSION['csrf']; }
function verifyCsrf(): void { $t=(string)($_POST['csrf'] ?? $_SERVER['HTTP_X_CSRF_TOKEN'] ?? ''); if(!$t || !hash_equals($_SESSION['csrf']??'', $t)) throw new RuntimeException('CSRF token tidak valid.'); }
function db(): ?PDO {
    static $initialized=false, $pdo=null;
    global $config;
    if($config['demo_mode']) return null;
    if($initialized) return $pdo;
    $initialized=true;
    if(!in_array('mysql', PDO::getAvailableDrivers(), true)){
        throw new RuntimeException('PDO MySQL tidak tersedia pada server. Aktifkan extension pdo_mysql sebelum menjalankan mode produksi.');
    }
    $d=$config['db'];
    try{
        $pdo=new PDO(
            "mysql:host={$d['host']};port={$d['port']};dbname={$d['name']};charset={$d['charset']}",
            $d['user'],$d['pass'],
            [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]
        );
        $pdo->exec("SET SESSION sql_mode='STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION'");
        return $pdo;
    }catch(Throwable $e){
        error_log('NEXA DB connection failed: '.$e->getMessage());
        throw new RuntimeException('Koneksi database produksi gagal. Aplikasi dihentikan agar tidak menampilkan data demo sebagai data nyata.',0,$e);
    }
}
