function loadStore(): array { global $config; if(!$config['demo_mode']) return loadDbStore(); $p=storagePath(); if(!is_file($p)){ $d=demoSeed(); @file_put_contents($p,json_encode($d,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE),LOCK_EX); return $d; } $d=json_decode((string)file_get_contents($p),true); if(!is_array($d))$d=demoSeed(); $seed=demoSeed(); foreach(['branches','departments','users','periods','approvals','invoices','bank_feed','bank_accounts','income_categories','currencies','tax_profiles','payments','eliminations','fx_events','integration_staging','parties','invoice_lines','payment_allocations','tax_transactions','asset_depreciation_schedule','reconciliation_sessions','consolidation_runs','elimination_entries','approval_decisions','fx_rates','fx_revaluation_runs','integration_outbox','period_close_tasks','asset_events','settlement_batches','bank_import_profiles','bank_statement_imports','approval_policies','invoice_adjustments','expense_categories','bank_transfers','opening_balance_batches','recurring_journal_templates','recurring_journal_runs','cash_forecast_items','year_end_closes','onboarding_import_jobs','onboarding_import_errors','ap_payment_batches','ap_payment_batch_lines','document_attachments','employee_advances','employee_advance_settlements','loan_facilities','loan_payments','equity_transactions','budget_scenarios','budget_scenario_lines'] as $k) if(!isset($d[$k]))$d[$k]=$seed[$k]; $d['meta']=array_merge($seed['meta'],$d['meta']??[]); return $d; }
function saveStore(array $d): void { $tmp=storagePath().'.tmp'; file_put_contents($tmp,json_encode($d,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE),LOCK_EX); rename($tmp,storagePath()); }
function loadDbStore(): array {
    $pdo=db();
    if(!$pdo) throw new RuntimeException('Database produksi tidak tersedia.');
    $companies=$pdo->query("SELECT id,code,name,business_type type,'violet' color FROM companies WHERE is_active=1 ORDER BY id")->fetchAll();
    $branches=$pdo->query("SELECT id,company_id,code,name,timezone,is_active active FROM branches WHERE is_active=1 ORDER BY company_id,code")->fetchAll();
    $departments=$pdo->query("SELECT id,company_id,branch_id,code,name,cost_center_code,profit_center_code,is_active active FROM departments WHERE is_active=1 ORDER BY company_id,branch_id,code")->fetchAll();
    $accounts=$pdo->query("SELECT id,company_id,code,name,account_type type,is_cash_bank cash FROM chart_accounts WHERE is_active=1 ORDER BY company_id,code")->fetchAll();
    $rows=$pdo->query("SELECT je.id,je.journal_no no,je.company_id,je.branch_id,je.department_id,je.journal_date date,je.description,je.status,je.source_type source,je.reversal_of,je.reversed_by,jl.account_id,jl.branch_id line_branch_id,jl.department_id line_department_id,jl.debit,jl.credit,jl.cost_center,jl.profit_center,jl.project_code,jl.transaction_currency,jl.foreign_amount,jl.exchange_rate,jl.base_amount,jl.intercompany_company_id FROM journal_entries je JOIN journal_lines jl ON jl.journal_id=je.id WHERE je.status='posted' ORDER BY je.journal_date,je.id,jl.id")->fetchAll();
    $entries=[];
    foreach($rows as $r){
        $id=(int)$r['id'];
        if(!isset($entries[$id])) $entries[$id]=['id'=>$id,'no'=>$r['no'],'company_id'=>(int)$r['company_id'],'branch_id'=>$r['branch_id']?(int)$r['branch_id']:null,'department_id'=>$r['department_id']?(int)$r['department_id']:null,'date'=>$r['date'],'description'=>$r['description'],'status'=>$r['status'],'source'=>$r['source'],'reversal_of'=>$r['reversal_of']?(int)$r['reversal_of']:null,'reversed_by'=>$r['reversed_by']?(int)$r['reversed_by']:null,'intercompany_company_id'=>$r['intercompany_company_id']?(int)$r['intercompany_company_id']:null,'lines'=>[]];
