function companyMap(array $s): array { $m=[]; foreach($s['companies'] as $c)$m[(int)$c['id']]=$c; return $m; }
function accountMap(array $s): array { $m=[]; foreach($s['accounts'] as $a)$m[(int)$a['id']]=$a; return $m; }
function entryBalanced(array $lines): bool { return (new \Nexa\Legacy\EnterpriseFacade())->entryBalanced($lines); }
function accountNormal(string $type): string { return in_array($type,['asset','expense'],true)?'debit':'credit'; }
function lineEffect(array $account, array $line): float { return accountNormal($account['type'])==='debit' ? ((float)$line['debit']-(float)$line['credit']) : ((float)$line['credit']-(float)$line['debit']); }
function metrics(array $s, ?int $companyId=null): array { $am=accountMap($s); $revenue=$expense=$cash=$assets=$liabilities=$equity=0.0; $tx=0; foreach($s['entries'] as $e){ if($e['status']!=='posted'||($companyId && (int)$e['company_id']!==$companyId))continue; $tx++; foreach($e['lines'] as $l){ $a=$am[(int)$l['account_id']]??null; if(!$a)continue; $eff=lineEffect($a,$l); if($a['type']==='revenue'){if(($e['source']??'')!=='year_end_close')$revenue+=$eff;} elseif($a['type']==='expense'){if(($e['source']??'')!=='year_end_close')$expense+=$eff;} elseif($a['type']==='asset')$assets+=$eff; elseif($a['type']==='liability')$liabilities+=$eff; elseif($a['type']==='equity')$equity+=$eff; if(!empty($a['cash']))$cash+=$eff; } } return compact('revenue','expense','cash','assets','liabilities','equity','tx')+['profit'=>$revenue-$expense,'margin'=>$revenue>0?($revenue-$expense)/$revenue*100:0]; }
function companyMetrics(array $s): array { $out=[]; foreach($s['companies'] as $c){ $m=metrics($s,(int)$c['id']); $out[]=array_merge($c,$m); } return $out; }
function transactions(array $s, int $limit=50): array { $cm=companyMap($s);$am=accountMap($s);$out=[]; $entries=array_reverse($s['entries']); foreach($entries as $e){ if($e['status']!=='posted')continue; $amount=0;$type='journal';$account='Jurnal Umum'; foreach($e['lines'] as $l){$a=$am[(int)$l['account_id']]??null;if(!$a)continue;if((float)$l['debit']>0)$amount=max($amount,(float)$l['debit']); if($a['type']==='revenue'&&$l['credit']>0){$type='income';$account=$a['name'];} if($a['type']==='expense'&&$l['debit']>0){$type='expense';$account=$a['name'];}} $out[]=['id'=>$e['id'],'no'=>$e['no'],'date'=>$e['date'],'company'=>$cm[(int)$e['company_id']]['name']??'-','desc'=>$e['description'],'account'=>$account,'amount'=>$amount,'type'=>$type,'status'=>ucfirst($e['status'])]; if(count($out)>=$limit)break;} return $out; }
function intercompanySummary(array $s): array { $cm=companyMap($s);$out=[]; foreach($s['entries'] as $e){$to=$e['intercompany_company_id']??null;if(!$to)continue;$amt=0;foreach($e['lines'] as $l)$amt=max($amt,(float)$l['debit'],(float)$l['credit']);$out[]=['date'=>$e['date'],'from'=>$cm[(int)$e['company_id']]['name']??'-','to'=>$cm[(int)$to]['name']??'-','description'=>$e['description'],'amount'=>$amt,'status'=>'Matched'];} return $out; }
function monthKeys(int $months=6, ?string $endKey=null): array {
    $months=max(1,min(24,$months));
    $end=$endKey && preg_match('/^\d{4}-\d{2}$/',$endKey)?DateTimeImmutable::createFromFormat('!Y-m',$endKey):new DateTimeImmutable('first day of this month');
    $out=[];for($i=$months-1;$i>=0;$i--)$out[]=$end->modify("-$i months")->format('Y-m');return $out;
}
function monthLabel(string $key): string { $map=['01'=>'Jan','02'=>'Feb','03'=>'Mar','04'=>'Apr','05'=>'Mei','06'=>'Jun','07'=>'Jul','08'=>'Agu','09'=>'Sep','10'=>'Okt','11'=>'Nov','12'=>'Des'];return ($map[substr($key,5,2)]??substr($key,5,2)).' '.substr($key,0,4); }
function metricsForPeriod(array $s,string $period,?int $companyId=null): array { $copy=$s;$copy['entries']=array_values(array_filter($s['entries']??[],fn($e)=>str_starts_with((string)$e['date'],$period)&&(!$companyId||(int)$e['company_id']===$companyId)));return metrics($copy,$companyId); }
function dashboardMetrics(array $s,string $period): array { $all=metrics($s);$p=metricsForPeriod($s,$period);foreach(['cash','assets','liabilities','equity'] as $k)$p[$k]=$all[$k];return $p; }
function companyMetricsForPeriod(array $s,string $period): array { $out=[];foreach($s['companies'] as $c){$all=metrics($s,(int)$c['id']);$p=metricsForPeriod($s,$period,(int)$c['id']);foreach(['cash','assets','liabilities','equity'] as $k)$p[$k]=$all[$k];$out[]=array_merge($c,$p);}return $out; }
function ledgerTrend(array $s,int $months=6,string $endKey=''): array { $keys=monthKeys($months,$endKey?:date('Y-m'));$out=[];foreach($keys as $k){$m=metricsForPeriod($s,$k);$out[]=['m'=>monthLabel($k),'revenue'=>round($m['revenue']/1000000,2),'expense'=>round($m['expense']/1000000,2)];}return $out; }
function cashflowTrend(array $s,int $months=6,string $endKey=''): array { $keys=monthKeys($months,$endKey?:date('Y-m'));$acc=accountMap($s);$rows=[];foreach($keys as $k)$rows[$k]=['m'=>monthLabel($k),'operating'=>0.0,'investing'=>0.0,'financing'=>0.0];foreach($s['entries']??[] as $e){$k=substr((string)$e['date'],0,7);if(!isset($rows[$k])||($e['status']??'')!=='posted')continue;$cash=0.0;$counterTypes=[];foreach($e['lines'] as $l){$a=$acc[(int)$l['account_id']]??null;if(!$a)continue;if(!empty($a['cash']))$cash+=(float)$l['debit']-(float)$l['credit'];else $counterTypes[]=$a['type'];}if(abs($cash)<0.005)continue;$bucket='operating';if(array_intersect($counterTypes,['equity','liability']))$bucket='financing';elseif(in_array('asset',$counterTypes,true))$bucket='investing';$rows[$k][$bucket]+=$cash/1000000;}return array_values($rows); }
