function budgetRowsForPeriod(array $s,string $period): array { [$y,$m]=array_map('intval',explode('-',$period));$rows=[];$am=accountMap($s);foreach($s['budgets']??[] as $b){if(isset($b['fiscal_year'])&&((int)$b['fiscal_year']!==$y||(int)$b['period']!==$m))continue;$cid=(int)$b['company_id'];$budget=(float)($b['budget']??0);if(isset($b['actual']))$actual=(float)$b['actual'];else{$actual=0.0;$aid=(int)($b['account_id']??0);foreach($s['entries']??[] as$e){if((int)$e['company_id']!==$cid||($e['status']??'')!=='posted'||substr((string)$e['date'],0,7)!==$period)continue;if(!empty($b['branch_id'])&&(int)($e['branch_id']??0)!==(int)$b['branch_id'])continue;if(!empty($b['department_id'])&&(int)($e['department_id']??0)!==(int)$b['department_id'])continue;foreach($e['lines']??[] as$l){if($aid&&(int)$l['account_id']!==$aid)continue;$a=$am[(int)$l['account_id']]??null;if(!$a)continue;$actual+=lineEffect($a,$l);}}}$rows[]=['company_id'=>$cid,'branch_id'=>$b['branch_id']??null,'department_id'=>$b['department_id']??null,'account_id'=>$b['account_id']??null,'budget'=>$budget,'actual'=>$actual];}return $rows; }
function validateJournalAccounts(array $s,int $company,int $debit,int $credit): void { $cm=companyMap($s);if(!isset($cm[$company]))throw new InvalidArgumentException('Badan usaha tidak ditemukan.');$am=accountMap($s);foreach([$debit,$credit] as $aid){$a=$am[$aid]??null;if(!$a)throw new InvalidArgumentException('Akun jurnal tidak ditemukan atau tidak aktif.');$owner=(int)($a['company_id']??0);if($owner!==0&&$owner!==$company)throw new RuntimeException('Akun jurnal bukan milik badan usaha yang dipilih.');} }
