function normalizeJournalInput(array $input): array { $j=['company'=>(int)($input['company_id']??0),'date'=>(string)($input['date']??date('Y-m-d')),'desc'=>trim((string)($input['description']??'')),'amount'=>(float)($input['amount']??0),'debit'=>(int)($input['debit_account_id']??0),'credit'=>(int)($input['credit_account_id']??0),'ic'=>(($input['intercompany_company_id']??'')!=='')?(int)$input['intercompany_company_id']:null];if(!$j['company']||!$j['desc']||$j['amount']<=0||!$j['debit']||!$j['credit']||$j['debit']===$j['credit'])throw new InvalidArgumentException('Data jurnal belum lengkap atau akun debit/kredit sama.');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$j['date']))throw new InvalidArgumentException('Format tanggal tidak valid.');return $j; }
