function normalizeDailyIncomeInput(array $input,array $s): array { $company=(int)($input['company_id']??0);$date=(string)($input['date']??date('Y-m-d'));$description=trim((string)($input['description']??'Pendapatan harian'));if(!$company||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||textLength($description)<3)throw new InvalidArgumentException('Badan usaha, tanggal, dan keterangan pendapatan wajib diisi.');$incomeRaw=$input['income_lines']??[];$paymentRaw=$input['payment_lines']??[];if(is_string($incomeRaw))$incomeRaw=json_decode($incomeRaw,true);if(is_string($paymentRaw))$paymentRaw=json_decode($paymentRaw,true);if(!is_array($incomeRaw)||!is_array($paymentRaw))throw new InvalidArgumentException('Detail pendapatan/pembayaran tidak valid.');$cats=[];foreach($s['income_categories']??[] as $c)if((int)$c['company_id']===$company&&!empty($c['active']))$cats[(int)$c['id']]=$c;$am=accountMap($s);$lines=[];$incomeTotal=0.0;$paymentTotal=0.0;$normalizedIncome=[];$normalizedPayment=[];foreach($incomeRaw as $r){$cid=(int)($r['category_id']??0);$amt=(float)($r['amount']??0);if($amt<=0)continue;$cat=$cats[$cid]??null;if(!$cat)throw new InvalidArgumentException('Kategori pendapatan tidak tersedia untuk badan usaha ini.');$aid=(int)$cat['revenue_account_id'];$a=$am[$aid]??null;if(!$a||($a['type']??'')!=='revenue')throw new RuntimeException('Kategori pendapatan harus dipetakan ke akun revenue aktif.');$lines[]=['account_id'=>$aid,'debit'=>0.0,'credit'=>$amt,'description'=>(string)$cat['name']];$normalizedIncome[]=['category_id'=>$cid,'name'=>$cat['name'],'amount'=>$amt,'account_id'=>$aid];$incomeTotal+=$amt;}foreach($paymentRaw as $r){$aid=(int)($r['account_id']??0);$amt=(float)($r['amount']??0);$label=trim((string)($r['label']??'Kas / Bank'));if($amt<=0)continue;$a=$am[$aid]??null;if(!$a||empty($a['cash']))throw new InvalidArgumentException('Pembayaran harus masuk ke akun kas/bank aktif.');$owner=(int)($a['company_id']??0);if($owner!==0&&$owner!==$company)throw new RuntimeException