function insertPostedMultiLineDb(PDO $pdo,array $j,string $source='daily_income'): array { $prefix=$source==='daily_income'?'INC':'JRN';$no=$prefix.'-'.str_replace('-','',substr($j['date'],0,7)).'-'.strtoupper(bin2hex(random_bytes(3)));$st=$pdo->prepare("INSERT INTO journal_entries(company_id,journal_no,journal_date,description,source_type,status,posted_at,created_by) VALUES(?,?,?,?,?,'posted',NOW(),?)");$st->execute([$j['company'],$no,$j['date'],$j['desc'],$source,$_SESSION['user_id']??null]);$jid=(int)$pdo->lastInsertId();$sl=$pdo->prepare("INSERT INTO journal_lines(journal_id,account_id,description,debit,credit,intercompany_company_id) VALUES(?,?,?,?,?,NULL)");foreach($j['lines'] as $l)$sl->execute([$jid,(int)$l['account_id'],(string)($l['description']??''),(float)$l['debit'],(float)$l['credit']]);return ['id'=>$jid,'no'=>$no,'status'=>'posted','source'=>$source,'amount'=>$j['amount']]; }
function postDailyIncome(array $input,bool $approvedOverride=false): array { global $config;$s=loadStore();requireAbility('income.manage',$s);$j=normalizeDailyIncomeInput($input,$s);enforceCompanyAccess($s,$j['company']);assertPeriodOpen($s,$j['date']);$threshold=(float)($s['meta']['approval_threshold']??25000000);$u=currentUser($s);$payload=['kind'=>'daily_income','company_id'=>$j['company'],'date'=>$j['date'],'description'=>$j['desc'],'income_lines'=>$j['income_lines'],'payment_lines'=>$j['payment_lines']];if($j['amount']>=$threshold&&!$approvedOverride){if($config['demo_mode']){$aid=(int)($s['meta']['next_approval_id']??1);$a=['id'=>$aid,'journal_id'=>null,'company_id'=>$j['company'],'date'=>$j['date'],'description'=>$j['desc'],'amount'=>$j['amount'],'requested_by'=>$u['id'],'status'=>'pending','requested_at'=>date('Y-m-d H:i:s'),'payload'=>$payload];$s['approvals'][]=$a;$s['meta']['next_approval_id']=$aid+1;saveStore($s);writeAudit('daily_income.approval_requested',['approval_id'=>$aid,'amount'=>$j['amount'],'company_id'=>$j['company']]);return ['approval_required'=>true,'approval'=>$a,'amount'=>$j['amount']];}$pdo=db();$st=$pdo->prepare("INSERT INTO journal_approvals(company_id,journal_date,description,amount,requested_by,status,payload_json) VALUES(?,?,?,?,?,'pending',?)");$st->execute([$j['company'],$j['date'],$j['desc'],$j['amount'],$u['id'],json_encode($payload,JSON_UNESCAPED_UNICODE)]);$aid=(int)$pdo->lastInsertId();writeAudit('daily_income.approval_requested',['approval_id'=>$aid,'amount'=>$j['amount'],'company_id'=>$j['company']]);return ['approval_required'=>true,'approval'=>['id'=>$aid,'status'=>'pending'],'amount'=>$j['amount']];}if($config['demo_mode']){$id=(int)($s['meta']['next_entry_id']??count($s['entries'])+1);$entry=['id'=>$id,'no'=>'INC-'.str_replace('-','',substr($j['date'],0,7)).'-'.str_pad((string)$id,4,'0',STR_PAD_LEFT),'company_id'=>$j['company'],'date'=>$j['date'],'description'=>$j['desc'],'status'=>'posted','source'=>'daily_income','intercompany_company_id'=>null,'lines'=>$j['lines']];$s['entries'][]=$entry;$s['meta']['next_entry_id']=$id+1;$s['meta']['version']=(int)($s['meta']['version']??0)+1;saveStore($s);writeAudit('daily_income.posted',['id'=>$id,'amount'=>$j['amount'],'company_id'=>$j['company']]);return $entry+['amount'=>$j['amount']];}$pdo=db();$pdo->beginTransaction();try{lockAndAssertPeriodOpenDb($pdo,$j['date']);$entry=insertPostedMultiLineDb($pdo,$j,'daily_income');$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}writeAudit('daily_income.posted',['id'=>$entry['id'],'amount'=>$j['amount'],'company_id'=>$j['company']]);return $entry; }
function createIncomeCategory(array $input): array { global $config;$s=loadStore();requireAbility('income.category.manage',$s);$company=(int)($input['company_id']??0);$name=trim((string)($input['name']??''));$code=strtoupper(trim((string)($input['code']??'')));$account=(int)($input['revenue_account_id']??0);if(!$company||textLength($name)<2||!preg_match('/^[A-Z0-9_-]{2,20}$/',$code)||!$account)throw new InvalidArgumentException('Data kategori pendapatan tidak valid.');enforceCompanyAccess($s,$company);$am=accountMap($s);$a=$am[$account]??null;if(!$a||($a['type']??'')!=='revenue')throw new InvalidArgumentException('Kategori harus dipetakan ke akun revenue.');foreach($s['income_categories']??[] as $c)if((int)$c['company_id']===$company&&strtoupper((string)$c['code'])===$code)throw new RuntimeException('Kode kategori sudah digunakan pada badan usaha ini.');if($config['demo_mode']){$id=(int)($s['meta']['next_income_category_id']??1);$row=['id'=>$id,'company_id'=>$company,'code'=>$code,'name'=>$name,'revenue_account_id'=>$account,'active'=>1,'sort_order'=>count($s['income_categories']??[])+10];$s['income_categories'][]=$row;$s['meta']['next_income_category_id']=$id+1;saveStore($s);writeAudit('income_category.created',['id'=>$id,'company_id'=>$company]);return $row;}$pdo=db();$st=$pdo->prepare("INSERT INTO income_categories(company_id,code,name,revenue_account_id,sort_order,is_active) VALUES(?,?,?,?,100,1)");$st->execute([$company,$code,$name,$account]);$row=['id'=>(int)$pdo->lastInsertId(),'company_id'=>$company,'code'=>$code,'name'=>$name,'revenue_account_id'=>$account,'active'=>1,'sort_order'=>100];writeAudit('income_category.created',['id'=>$row['id'],'company_id'=>$company]);return $row; }

function loginIdentifierHash(string $email): string { return hash('sha256',strtolower(trim($email))); }
function loginRateAllowed(PDO $pdo,string $email,string $ip,int $max=8,int $minutes=15): bool { $st=$pdo->prepare("SELECT COUNT(*) FROM login_attempts WHERE identifier_hash=? AND ip_address=? AND success=0 AND attempted_at>=DATE_SUB(NOW(),INTERVAL ? MINUTE)");$st->execute([loginIdentifierHash($email),$ip,$minutes]);return (int)$st->fetchColumn()<$max; }
function recordLoginAttempt(PDO $pdo,string $email,string $ip,bool $success): void { $st=$pdo->prepare("INSERT INTO login_attempts(identifier_hash,ip_address,success) VALUES(?,?,?)");$st->execute([loginIdentifierHash($email),$ip,$success?1:0]);if($success){$pdo->prepare("DELETE FROM login_attempts WHERE identifier_hash=? AND ip_address=? AND success=0")->execute([loginIdentifierHash($email),$ip]);}$pdo->exec("DELETE FROM login_attempts WHERE attempted_at<DATE_SUB(NOW(),INTERVAL 2 DAY)"); }
function currentUser(array $s): array { global $config; if($config['demo_mode']){ $id=(int)($_SESSION['user_id']??1); foreach(($s['users']??[]) as $u) if((int)$u['id']===$id) return $u; return ['id'=>1,'name'=>'Group Owner','email'=>'owner@nexa.local','role'=>'group_owner','active'=>1]; } $id=(int)($_SESSION['user_id']??0); if(!$id)return []; foreach(($s['users']??[]) as $u)if((int)$u['id']===$id&&!empty($u['active']))return $u; return []; }
function isAuthenticated(): bool { global $config; if($config['demo_mode'])return true; return !empty($_SESSION['user_id']); }
function requireLogin(bool $api=false): void { if(isAuthenticated())return; if($api)jsonOut(['ok'=>false,'message'=>'Autentikasi diperlukan.'],401); header('Location: login.php'); exit; }
function scopeStoreForUser(array $s,array $u): array {
    if(($u['role']??'')!=='entity_admin')return $s;
    $cid=(int)($u['company_id']??0);
    $direct=['companies','accounts','entries','branches','departments','budgets','assets','invoices','bank_feed','bank_accounts','approvals','payments','integration_staging','fx_events','eliminations','parties','tax_transactions','expense_categories','bank_transfers','opening_balance_batches','cash_forecast_items','year_end_closes','onboarding_import_jobs','ap_payment_batches','document_attachments','employee_advances','loan_facilities','equity_transactions','budget_scenarios'];
    if(!$cid){foreach(array_merge($direct,['recurring_journal_templates','recurring_journal_runs','onboarding_import_errors','ap_payment_batch_lines','employee_advance_settlements','loan_payments','budget_scenario_lines']) as $k)$s[$k]=[];return $s;}
    $s['companies']=array_values(array_filter($s['companies']??[],fn($r)=>(int)$r['id']===$cid));
    $s['accounts']=array_values(array_filter($s['accounts']??[],fn($r)=>(int)($r['company_id']??0)===0||(int)($r['company_id']??0)===$cid));
    $s['entries']=array_values(array_filter($s['entries']??[],fn($r)=>(int)$r['company_id']===$cid));
    foreach(array_diff($direct,['companies','accounts','entries','eliminations']) as $k)$s[$k]=array_values(array_filter($s[$k]??[],fn($r)=>(int)($r['company_id']??0)===$cid));
    $s['recurring_journal_templates']=array_values(array_filter($s['recurring_journal_templates']??[],fn($r)=>(int)($r['company_id']??0)===$cid));
    $recIds=array_flip(array_map(fn($r)=>(int)$r['id'],$s['recurring_journal_templates']));
    $s['recurring_journal_runs']=array_values(array_filter($s['recurring_journal_runs']??[],fn($r)=>isset($recIds[(int)($r['template_id']??0)])));
    $jobIds=array_flip(array_map(fn($r)=>(int)$r['id'],$s['onboarding_import_jobs']??[]));
    $s['onboarding_import_errors']=array_values(array_filter($s['onboarding_import_errors']??[],fn($r)=>isset($jobIds[(int)($r['job_id']??0)])));
    $batchIds=array_flip(array_map(fn($r)=>(int)$r['id'],$s['ap_payment_batches']??[]));
    $s['ap_payment_batch_lines']=array_values(array_filter($s['ap_payment_batch_lines']??[],fn($r)=>isset($batchIds[(int)($r['batch_id']??0)])));
    $s['eliminations']=array_values(array_filter($s['eliminations']??[],fn($r)=>(int)($r['from_company_id']??0)===$cid||(int)($r['to_company_id']??0)===$cid));
    return $s;
}
function roleCan(string $role,string $ability): bool { static $svc=null;global $config;$aliases=['journal.create'=>'journal.post','journal.approve'=>'approval.decide','period.manage'=>'period.close','intercompany.eliminate'=>'consolidation.manage','income.category.manage'=>'income.manage','backup.create'=>'backup.manage','user.manage'=>'user.manage','company.manage'=>'company.manage','audit.view'=>'audit.view'];$permission=$aliases[$ability]??$ability;if($svc===null){$pdo=null;if(!$config['demo_mode']){try{$pdo=db();}catch(Throwable){$pdo=null;}}$svc=new \Nexa\Security\RbacService($pdo);}return $svc->can($role,$permission); }
function enforceCompanyAccess(array $s,int $companyId): void { $u=currentUser($s); if(!$u)throw new RuntimeException('Autentikasi diperlukan.'); if(($u['role']??'')==='entity_admin' && (int)($u['company_id']??0)!==$companyId) throw new RuntimeException('Entity Admin hanya dapat mengelola badan usaha yang ditugaskan.'); }
function requireAbility(string $ability, ?array $store=null): void { $s=$store??loadStore(); $u=currentUser($s); if(!$u)throw new RuntimeException('Autentikasi diperlukan.'); if(!roleCan((string)$u['role'],$ability)) throw new RuntimeException('Akses ditolak untuk role '.$u['role'].'.'); }
function periodStatus(array $s,string $date): string { $ts=strtotime($date);$y=(int)date('Y',$ts);$m=(int)date('n',$ts); foreach(($s['periods']??[]) as $p) if((int)$p['year']===$y&&(int)$p['month']===$m)return (string)$p['status']; return 'open'; }
function assertPeriodOpen(array $s,string $date): void { if(periodStatus($s,$date)!=='open') throw new RuntimeException('Periode akuntansi '.date('m/Y',strtotime($date)).' sudah ditutup.'); }
function agingBucket(string $dueDate,?string $asOf=null): string { $asOf=$asOf?:date('Y-m-d'); $days=(int)floor((strtotime($asOf)-strtotime($dueDate))/86400); if($days<=0)return 'Current'; if($days<=30)return '1-30'; if($days<=60)return '31-60'; if($days<=90)return '61-90'; return '90+'; }
function arapSummary(array $s): array { $out=['receivable'=>0.0,'payable'=>0.0,'overdue_receivable'=>0.0,'overdue_payable'=>0.0,'rows'=>[],'aging'=>['Current'=>0.0,'1-30'=>0.0,'31-60'=>0.0,'61-90'=>0.0,'90+'=>0.0]]; foreach(($s['invoices']??[]) as $i){$open=max(0,(float)$i['amount']-(float)$i['paid']);$type=(string)$i['type'];$out[$type]+=$open;$bucket=agingBucket((string)$i['due_date']);if($type==='receivable')$out['aging'][$bucket]+=$open;if(strtotime((string)$i['due_date'])<strtotime(date('Y-m-d'))&&$open>0)$out['overdue_'.$type]+=$open;$r=$i;$r['open']=$open;$r['bucket']=$bucket;$out['rows'][]=$r;} return $out; }
function bankReconciliationSummary(array $s): array { $matched=$unmatched=$in=$out=0.0;$rows=$s['bank_feed']??[]; foreach($rows as $r){$amt=(float)$r['amount']; if($r['status']==='matched')$matched+=$amt;else$unmatched+=$amt;if($r['direction']==='in')$in+=$amt;else$out+=$amt;} return compact('matched','unmatched','in','out','rows')+['match_rate'=>($matched+$unmatched)>0?$matched/($matched+$unmatched)*100:0]; }
function approvalSummary(array $s): array { $pending=0.0;$approved=0.0;$count=0;foreach(($s['approvals']??[]) as $a){if($a['status']==='pending'){$pending+=(float)$a['amount'];$count++;}elseif($a['status']==='approved')$approved+=(float)$a['amount'];}return compact('pending','approved','count')+['rows'=>$s['approvals']??[]]; }
function closePeriod(int $year,int $month): array { global $config;if($year<2000||$month<1||$month>12)throw new InvalidArgumentException('Periode tidak valid.');$s=loadStore();requireAbility('period.manage',$s);$u=currentUser($s);$prefix=sprintf('%04d-%02d',$year,$month);$pending=array_filter($s['approvals']??[],fn($a)=>($a['status']??'')==='pending'&&str_starts_with((string)($a['date']??''),$prefix));if($pending)throw new RuntimeException('Periode belum dapat ditutup karena masih ada approval jurnal pending.');if($config['demo_mode']){$found=false;foreach($s['periods'] as &$p){if((int)$p['year']===$year&&(int)$p['month']===$month){$p['status']='closed';$p['closed_at']=date('Y-m-d H:i:s');$p['closed_by']=$u['id'];$found=true;}}unset($p);if(!$found)$s['periods'][]=['id'=>count($s['periods'])+1,'year'=>$year,'month'=>$month,'status'=>'closed','closed_at'=>date('Y-m-d H:i:s'),'closed_by'=>$u['id']];saveStore($s);writeAudit('period.closed',['year'=>$year,'month'=>$month]);return ['year'=>$year,'month'=>$month,'status'=>'closed'];}$pdo=db();$pdo->beginTransaction();try{$pdo->prepare("INSERT INTO fiscal_periods(fiscal_year,period,status) VALUES(?,?,'open') ON DUPLICATE KEY UPDATE id=id")->execute([$year,$month]);$st=$pdo->prepare("SELECT status FROM fiscal_periods WHERE fiscal_year=? AND period=? FOR UPDATE");$st->execute([$year,$month]);$st->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM journal_approvals WHERE status='pending' AND YEAR(journal_date)=? AND MONTH(journal_date)=?");$q->execute([$year,$month]);if((int)$q->fetchColumn()>0)throw new RuntimeException('Periode belum dapat ditutup karena masih ada approval jurnal pending.');$up=$pdo->prepare("UPDATE fiscal_periods SET status='closed',closed_at=NOW(),closed_by=? WHERE fiscal_year=? AND period=?");$up->execute([$u['id'],$year,$month]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}writeAudit('period.closed',['year'=>$year,'month'=>$month]);return ['year'=>$year,'month'=>$month,'status'=>'closed']; }
function reconcileBank(int $bankId,int $journalId): array { global $config;$s=loadStore();requireAbility('bank.reconcile',$s);if($bankId<=0||$journalId<=0)throw new InvalidArgumentException('Mutasi bank dan jurnal wajib dipilih.');$bank=null;foreach($s['bank_feed']??[] as $r)if((int)$r['id']===$bankId)$bank=$r;$entry=findEntry($s,$journalId);if(!$bank||!$entry)throw new InvalidArgumentException('Mutasi bank atau jurnal tidak ditemukan.');enforceCompanyAccess($s,(int)$bank['company_id']);if((int)$entry['company_id']!==(int)$bank['company_id'])throw new RuntimeException('Jurnal dan mutasi bank harus berasal dari badan usaha yang sama.');$am=accountMap($s);$cash=0.0;foreach($entry['lines'] as $l){$a=$am[(int)$l['account_id']]??null;if($a&&!empty($a['cash']))$cash+=(float)$l['debit']-(float)$l['credit'];}$expected=$bank['direction']==='in'?(float)$bank['amount']:-(float)$bank['amount'];if(abs($cash-$expected)>0.01)throw new RuntimeException('Nominal/direction jurnal kas tidak cocok dengan mutasi bank.');if(($bank['status']??'')!=='unmatched')throw new RuntimeException('Mutasi bank sudah direkonsiliasi atau diabaikan.');if($config['demo_mode']){foreach($s['bank_feed'] as &$r)if((int)$r['id']===$bankId){$r['status']='matched';$r['journal_id']=$journalId;$bank=$r;}unset($r);saveStore($s);writeAudit('bank.reconciled',['bank_id'=>$bankId,'journal_id'=>$journalId]);return $bank;}$pdo=db();$pdo->beginTransaction();try{$st=$pdo->prepare("SELECT status FROM bank_feed WHERE id=? FOR UPDATE");$st->execute([$bankId]);if($st->fetchColumn()!=='unmatched')throw new RuntimeException('Mutasi bank sudah direkonsiliasi atau diabaikan.');$up=$pdo->prepare("UPDATE bank_feed SET status='matched',journal_id=? WHERE id=? AND status='unmatched'");$up->execute([$journalId,$bankId]);if($up->rowCount()!==1)throw new RuntimeException('Rekonsiliasi gagal karena data berubah.');$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}writeAudit('bank.reconciled',['bank_id'=>$bankId,'journal_id'=>$journalId]);return ['id'=>$bankId,'journal_id'=>$journalId,'status'=>'matched']; }
function decideApproval(int $id,string $decision): array { global $config;$s=loadStore();requireAbility('journal.approve',$s);if(!in_array($decision,['approved','rejected'],true))throw new InvalidArgumentException('Keputusan approval tidak valid.');$u=currentUser($s);
    if($config['demo_mode']){
        $found=null;foreach($s['approvals'] as $a)if((int)$a['id']===$id){$found=$a;break;}if(!$found)throw new InvalidArgumentException('Approval tidak ditemukan.');if($found['status']!=='pending')throw new RuntimeException('Approval sudah diputuskan.');$posted=null;if($decision==='approved'){if(!is_array($found['payload']??null))throw new RuntimeException('Payload approval tidak lengkap.');$posted=(($found['payload']['kind']??'')==='daily_income')?postDailyIncome($found['payload'],true):postJournal($found['payload'],true);$s=loadStore();}foreach($s['approvals'] as &$a)if((int)$a['id']===$id){$a['status']=$decision;$a['decided_at']=date('Y-m-d H:i:s');$a['decided_by']=$u['id'];if($posted)$a['journal_id']=$posted['id']??null;$row=$a;}unset($a);saveStore($s);if($posted)$row['posted_entry']=$posted;writeAudit('approval.'.$decision,['approval_id'=>$id]);return $row;
    }
    $pdo=db();$pdo->beginTransaction();try{$st=$pdo->prepare("SELECT * FROM journal_approvals WHERE id=? FOR UPDATE");$st->execute([$id]);$row=$st->fetch();if(!$row)throw new InvalidArgumentException('Approval tidak ditemukan.');if($row['status']!=='pending')throw new RuntimeException('Approval sudah diputuskan.');$posted=null;if($decision==='approved'){$payload=$row['payload_json']?json_decode((string)$row['payload_json'],true):null;if(!is_array($payload))throw new RuntimeException('Payload approval tidak lengkap.');if(($payload['kind']??'')==='daily_income'){$j=normalizeDailyIncomeInput($payload,$s);requireAbility('income.manage',$s);enforceCompanyAccess($s,$j['company']);lockAndAssertPeriodOpenDb($pdo,$j['date']);$posted=insertPostedMultiLineDb($pdo,$j,'daily_income');}else{$j=normalizeJournalInput($payload);requireAbility('journal.create',$s);enforceCompanyAccess($s,$j['company']);validateJournalAccounts($s,$j['company'],$j['debit'],$j['credit']);validateIntercompany($s,$j['company'],$j['ic']);lockAndAssertPeriodOpenDb($pdo,$j['date']);$posted=insertPostedJournalDb($pdo,$j,'manual');}}$up=$pdo->prepare("UPDATE journal_approvals SET status=?,journal_id=?,decided_at=NOW(),decided_by=? WHERE id=?");$up->execute([$decision,$posted['id']??null,$u['id'],$id]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}writeAudit('approval.'.$decision,['approval_id'=>$id,'journal_id'=>$posted['id']??null]);$row['status']=$decision;if($posted)$row['posted_entry']=$posted;return $row;
}
function writeAudit(string $action, array $payload=[]): void { global $config;$name=$_SESSION['user_name']??'system'; $r=['at'=>date('c'),'user'=>$name,'action'=>$action,'ip'=>$_SERVER['REMOTE_ADDR']??'cli','payload'=>$payload]; @file_put_contents(auditPath(),json_encode($r,JSON_UNESCAPED_UNICODE).PHP_EOL,FILE_APPEND|LOCK_EX); if(!$config['demo_mode']){try{$pdo=db();if($pdo){$st=$pdo->prepare("INSERT INTO audit_logs(user_id,action,entity_type,entity_id,payload_json,ip_address) VALUES(?,?,?,?,?,?)");$st->execute([$_SESSION['user_id']??null,$action,$payload['entity_type']??'system',(string)($payload['id']??$payload['approval_id']??''),json_encode($payload,JSON_UNESCAPED_UNICODE),$_SERVER['REMOTE_ADDR']??'cli']);}}catch(Throwable $e){error_log('NEXA audit DB: '.$e->getMessage());}} }
function postJournal(array $input,bool $approvedOverride=false): array { global $config;$j=normalizeJournalInput($input);$lines=[['account_id'=>$j['debit'],'debit'=>$j['amount'],'credit'=>0],['account_id'=>$j['credit'],'debit'=>0,'credit'=>$j['amount']]];if(!entryBalanced($lines))throw new RuntimeException('Jurnal tidak balance.');$s=loadStore();requireAbility('journal.create',$s);enforceCompanyAccess($s,$j['company']);validateJournalAccounts($s,$j['company'],$j['debit'],$j['credit']);validateIntercompany($s,$j['company'],$j['ic']);assertPeriodOpen($s,$j['date']);$threshold=(float)($s['meta']['approval_threshold']??25000000);
    if($config['demo_mode']){
        if($j['amount']>=$threshold&&!$approvedOverride){$aid=(int)($s['meta']['next_approval_id']??1);$payload=['company_id'=>$j['company'],'date'=>$j['date'],'description'=>$j['desc'],'amount'=>$j['amount'],'debit_account_id'=>$j['debit'],'credit_account_id'=>$j['credit'],'intercompany_company_id'=>$j['ic']];$a=['id'=>$aid,'journal_id'=>null,'company_id'=>$j['company'],'date'=>$j['date'],'description'=>$j['desc'],'amount'=>$j['amount'],'requested_by'=>currentUser($s)['id'],'status'=>'pending','requested_at'=>date('Y-m-d H:i:s'),'payload'=>$payload];$s['approvals'][]=$a;$s['meta']['next_approval_id']=$aid+1;saveStore($s);writeAudit('journal.approval_requested',['approval_id'=>$aid,'amount'=>$j['amount']]);return ['approval_required'=>true,'approval'=>$a];}
        $id=(int)($s['meta']['next_entry_id']??(count($s['entries'])+1));$entry=['id'=>$id,'no'=>'JRN-'.str_replace('-','',substr($j['date'],0,7)).'-'.str_pad((string)$id,4,'0',STR_PAD_LEFT),'company_id'=>$j['company'],'date'=>$j['date'],'description'=>$j['desc'],'status'=>'posted','source'=>'manual','intercompany_company_id'=>$j['ic'],'lines'=>$lines];$s['entries'][]=$entry;$s['meta']['next_entry_id']=$id+1;$s['meta']['version']=(int)($s['meta']['version']??0)+1;saveStore($s);writeAudit('journal.posted',['id'=>$id,'amount'=>$j['amount']]);return $entry;
    }
    $pdo=db();if($j['amount']>=$threshold&&!$approvedOverride){$u=currentUser($s);$payload=['company_id'=>$j['company'],'date'=>$j['date'],'description'=>$j['desc'],'amount'=>$j['amount'],'debit_account_id'=>$j['debit'],'credit_account_id'=>$j['credit'],'intercompany_company_id'=>$j['ic']];$st=$pdo->prepare("INSERT INTO journal_approvals(company_id,journal_date,description,amount,requested_by,status,payload_json) VALUES(?,?,?,?,?,'pending',?)");$st->execute([$j['company'],$j['date'],$j['desc'],$j['amount'],$u['id'],json_encode($payload,JSON_UNESCAPED_UNICODE)]);$aid=(int)$pdo->lastInsertId();writeAudit('journal.approval_requested',['approval_id'=>$aid,'amount'=>$j['amount']]);return ['approval_required'=>true,'approval'=>['id'=>$aid,'status'=>'pending']];}
    $pdo->beginTransaction();try{lockAndAssertPeriodOpenDb($pdo,$j['date']);$entry=insertPostedJournalDb($pdo,$j,'manual');$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}writeAudit('journal.posted',['id'=>$entry['id'],'amount'=>$j['amount']]);return $entry;
}

function findEntry(array $s,int $id): ?array { foreach(($s['entries']??[]) as $e)if((int)$e['id']===$id)return $e; return null; }
function journalAmount(array $e): float { $m=0.0;foreach(($e['lines']??[]) as $l)$m=max($m,(float)$l['debit'],(float)$l['credit']);return $m; }
function reverseJournal(int $id,string $reason): array { global $config;$reason=trim($reason);if($id<=0||$reason==='')throw new InvalidArgumentException('Jurnal dan alasan reversal wajib diisi.');$s=loadStore();requireAbility('journal.reverse',$s);$orig=findEntry($s,$id);if(!$orig)throw new InvalidArgumentException('Jurnal tidak ditemukan.');enforceCompanyAccess($s,(int)$orig['company_id']);$reverseDate=date('Y-m-d');assertPeriodOpen($s,$reverseDate);if(($orig['status']??'')!=='posted')throw new RuntimeException('Hanya jurnal posted yang dapat direversal.');if(!empty($orig['reversal_of'])||!empty($orig['reversed_by']))throw new RuntimeException('Jurnal reversal/yang sudah direversal tidak dapat direversal ulang.');$lines=array_map(fn($l)=>['account_id'=>(int)$l['account_id'],'debit'=>(float)$l['credit'],'credit'=>(float)$l['debit']],$orig['lines']);if(!entryBalanced($lines))throw new RuntimeException('Reversal gagal balance.');
    if($config['demo_mode']){$nid=(int)($s['meta']['next_entry_id']??count($s['entries'])+1);$rev=['id'=>$nid,'no'=>'REV-'.date('Ym').'-'.str_pad((string)$nid,4,'0',STR_PAD_LEFT),'company_id'=>(int)$orig['company_id'],'date'=>$reverseDate,'description'=>'REVERSAL '.$orig['no'].' · '.$reason,'status'=>'posted','source'=>'reversal','intercompany_company_id'=>$orig['intercompany_company_id']??null,'reversal_of'=>$id,'lines'=>$lines];foreach($s['entries'] as &$e)if((int)$e['id']===$id)$e['reversed_by']=$nid;unset($e);$s['entries'][]=$rev;$s['meta']['next_entry_id']=$nid+1;saveStore($s);writeAudit('journal.reversed',['id'=>$id,'reversal_id'=>$nid,'reason'=>$reason]);return $rev;}
    $pdo=db();$pdo->beginTransaction();try{lockAndAssertPeriodOpenDb($pdo,$reverseDate);$lock=$pdo->prepare("SELECT reversal_of,reversed_by,status FROM journal_entries WHERE id=? FOR UPDATE");$lock->execute([$id]);$dbOrig=$lock->fetch();if(!$dbOrig||$dbOrig['status']!=='posted')throw new RuntimeException('Jurnal tidak tersedia untuk reversal.');if(!empty($dbOrig['reversal_of'])||!empty($dbOrig['reversed_by']))throw new RuntimeException('Jurnal reversal/yang sudah direversal tidak dapat direversal ulang.');$no='REV-'.date('YmHis').'-'.$id;$st=$pdo->prepare("INSERT INTO journal_entries(company_id,journal_no,journal_date,description,status,source_type,created_by,posted_at,reversal_of) VALUES(?,?,?,?, 'posted','reversal',?,NOW(),?)");$st->execute([$orig['company_id'],$no,$reverseDate,'REVERSAL '.$orig['no'].' · '.$reason,$_SESSION['user_id']??null,$id]);$nid=(int)$pdo->lastInsertId();$li=$pdo->prepare("INSERT INTO journal_lines(journal_id,account_id,debit,credit,intercompany_company_id) VALUES(?,?,?,?,?)");foreach($lines as $l)$li->execute([$nid,$l['account_id'],$l['debit'],$l['credit'],$orig['intercompany_company_id']??null]);$pdo->prepare("UPDATE journal_entries SET reversed_by=? WHERE id=?")->execute([$nid,$id]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}writeAudit('journal.reversed',['id'=>$id,'reversal_id'=>$nid,'reason'=>$reason]);return ['id'=>$nid,'no'=>$no,'status'=>'posted'];
}
function allocateInvoicePayment(int $invoiceId,float $amount,string $date,string $method='bank',string $reference=''): array { global $config;if($invoiceId<=0||$amount<=0||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new InvalidArgumentException('Invoice, nominal, atau tanggal pembayaran tidak valid.');$s=loadStore();requireAbility('arap.manage',$s);$inv=null;foreach(($s['invoices']??[]) as $i)if((int)$i['id']===$invoiceId)$inv=$i;if(!$inv)throw new InvalidArgumentException('Invoice tidak ditemukan.');enforceCompanyAccess($s,(int)$inv['company_id']);assertPeriodOpen($s,$date);$threshold=(float)($s['meta']['approval_threshold']??25000000);$u=currentUser($s);if($amount>=$threshold&&!roleCan((string)($u['role']??''),'journal.approve'))throw new RuntimeException('Pembayaran di atas batas approval harus diproses Group Finance/Owner.');$cashAccount=accountIdByCode($s,(int)$inv['company_id'],'1101');$arAccount=accountIdByCode($s,(int)$inv['company_id'],'1102');$apAccount=accountIdByCode($s,(int)$inv['company_id'],'2101');$debit=$inv['type']==='receivable'?$cashAccount:$apAccount;$credit=$inv['type']==='receivable'?$arAccount:$cashAccount;validateJournalAccounts($s,(int)$inv['company_id'],$debit,$credit);
    if($config['demo_mode']){$open=max(0,(float)$inv['amount']-(float)$inv['paid']);if($amount>$open+0.005)throw new RuntimeException('Pembayaran melebihi saldo invoice.');$entry=postJournal(['company_id'=>$inv['company_id'],'date'=>$date,'description'=>'Pembayaran '.$inv['number'].' · '.$inv['party'],'amount'=>$amount,'debit_account_id'=>$debit,'credit_account_id'=>$credit],true);$pid=(int)($s['meta']['next_payment_id']??1);$s=loadStore();foreach($s['invoices'] as &$i)if((int)$i['id']===$invoiceId){$i['paid']=(float)$i['paid']+$amount;$i['status']=$i['paid']+0.005>=(float)$i['amount']?'paid':'partial';$inv=$i;}unset($i);$pay=['id'=>$pid,'invoice_id'=>$invoiceId,'company_id'=>$inv['company_id'],'date'=>$date,'amount'=>$amount,'method'=>$method,'reference'=>$reference,'journal_id'=>$entry['id']];$s['payments'][]=$pay;$s['meta']['next_payment_id']=$pid+1;saveStore($s);writeAudit('invoice.payment_allocated',['invoice_id'=>$invoiceId,'payment_id'=>$pid,'amount'=>$amount]);return $pay;}
    $pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare("SELECT id,company_id,invoice_type,invoice_no,party_name,amount,paid_amount,status FROM invoices WHERE id=? FOR UPDATE");$q->execute([$invoiceId]);$locked=$q->fetch();if(!$locked||$locked['status']==='void')throw new RuntimeException('Invoice tidak tersedia.');$open=max(0,(float)$locked['amount']-(float)$locked['paid_amount']);if($amount>$open+0.005)throw new RuntimeException('Pembayaran melebihi saldo invoice.');lockAndAssertPeriodOpenDb($pdo,$date);$j=['company'=>(int)$locked['company_id'],'date'=>$date,'desc'=>'Pembayaran '.$locked['invoice_no'].' · '.$locked['party_name'],'amount'=>$amount,'debit'=>$debit,'credit'=>$credit,'ic'=>null];$entry=insertPostedJournalDb($pdo,$j,'arap_payment');$pdo->prepare("UPDATE invoices SET paid_amount=paid_amount+?, status=CASE WHEN paid_amount+?>=amount THEN 'paid' ELSE 'partial' END WHERE id=?")->execute([$amount,$amount,$invoiceId]);$st=$pdo->prepare("INSERT INTO invoice_payments(invoice_id,company_id,payment_date,amount,method,reference_no,journal_id,created_by) VALUES(?,?,?,?,?,?,?,?)");$st->execute([$invoiceId,$locked['company_id'],$date,$amount,$method,$reference,$entry['id'],$u['id']]);$pid=(int)$pdo->lastInsertId();$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}writeAudit('invoice.payment_allocated',['invoice_id'=>$invoiceId,'payment_id'=>$pid,'amount'=>$amount]);return ['id'=>$pid,'journal_id'=>$entry['id'],'amount'=>$amount];
}
function createElimination(int $from,int $to,float $amount,string $period,string $description): array { global $config;$s=loadStore();requireAbility('intercompany.eliminate',$s);if($from<=0||$to<=0||$from===$to||$amount<=0||!preg_match('/^\d{4}-\d{2}$/',$period))throw new InvalidArgumentException('Data eliminasi intercompany tidak valid.');$cm=companyMap($s);if(!isset($cm[$from])||!isset($cm[$to]))throw new InvalidArgumentException('Badan usaha eliminasi tidak ditemukan.');assertPeriodOpen($s,$period.'-01');$row=['from_company_id'=>$from,'to_company_id'=>$to,'amount'=>$amount,'period'=>$period,'description'=>trim($description)?:'Intercompany elimination','status'=>'posted','created_at'=>date('Y-m-d H:i:s')];if($config['demo_mode']){$id=(int)($s['meta']['next_elimination_id']??1);$row['id']=$id;$s['eliminations'][]=$row;$s['meta']['next_elimination_id']=$id+1;saveStore($s);writeAudit('intercompany.eliminated',['id'=>$id,'amount'=>$amount,'period'=>$period]);return $row;}$pdo=db();$pdo->beginTransaction();try{lockAndAssertPeriodOpenDb($pdo,$period.'-01');$st=$pdo->prepare("INSERT INTO intercompany_eliminations(period_key,from_company_id,to_company_id,amount,description,status,created_by) VALUES(?,?,?,?,?,'posted',?)");$st->execute([$period,$from,$to,$amount,$row['description'],$_SESSION['user_id']??null]);$row['id']=(int)$pdo->lastInsertId();$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}writeAudit('intercompany.eliminated',['id'=>$row['id'],'amount'=>$amount,'period'=>$period]);return $row;}
function eliminationSummary(array $s): array { $total=0.0;foreach(($s['eliminations']??[]) as $r)if(($r['status']??'')==='posted')$total+=(float)$r['amount'];return ['total'=>$total,'count'=>count($s['eliminations']??[]),'rows'=>$s['eliminations']??[]]; }
function taxSummary(array $s): array { $active=array_values(array_filter($s['tax_profiles']??[],fn($x)=>!empty($x['active'])));return ['profiles'=>$active,'count'=>count($active)]; }
function calculateTax(float $base,float $rate,bool $inclusive=false): array { if($base<0||$rate<0)throw new InvalidArgumentException('Nilai pajak tidak valid.');$r=(new \Nexa\Legacy\EnterpriseFacade())->tax((int)round($base),$rate,$inclusive);return ['base'=>(float)$r['base'],'tax'=>(float)$r['tax'],'gross'=>(float)$r['gross'],'rate'=>$rate]; }
function recordFxEvent(int $company,string $date,string $currency,float $foreign,float $bookRate,float $settlementRate,string $description=''): array { global $config;$s=loadStore();requireAbility('fx.manage',$s);enforceCompanyAccess($s,$company);assertPeriodOpen($s,$date);$currency=strtoupper(trim($currency));$known=array_column($s['currencies']??[],'code');if($currency==='IDR'||!in_array($currency,$known,true)||$foreign<=0||$bookRate<=0||$settlementRate<=0)throw new InvalidArgumentException('Data FX atau mata uang tidak valid.');$base=$foreign*$bookRate;$settled=$foreign*$settlementRate;$gainLoss=$settled-$base;$row=['company_id'=>$company,'date'=>$date,'currency'=>$currency,'foreign_amount'=>$foreign,'book_rate'=>$bookRate,'settlement_rate'=>$settlementRate,'base_amount'=>$base,'gain_loss'=>$gainLoss,'description'=>$description];if($config['demo_mode']){$row['id']=count($s['fx_events']??[])+1;$s['fx_events'][]=$row;saveStore($s);writeAudit('fx.recorded',['id'=>$row['id'],'gain_loss'=>$gainLoss]);return $row;}$pdo=db();$pdo->beginTransaction();try{lockAndAssertPeriodOpenDb($pdo,$date);$st=$pdo->prepare("INSERT INTO fx_events(company_id,event_date,currency,foreign_amount,book_rate,settlement_rate,base_amount,gain_loss,description,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)");$st->execute([$company,$date,$currency,$foreign,$bookRate,$settlementRate,$base,$gainLoss,$description,$_SESSION['user_id']??null]);$row['id']=(int)$pdo->lastInsertId();$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}writeAudit('fx.recorded',['id'=>$row['id'],'gain_loss'=>$gainLoss]);return $row;}
function fxSummary(array $s): array { $gl=0.0;foreach(($s['fx_events']??[]) as $r)$gl+=(float)$r['gain_loss'];return ['gain_loss'=>$gl,'count'=>count($s['fx_events']??[]),'rows'=>$s['fx_events']??[]]; }
function importBankCsv(int $companyId,string $csv): array { global $config;$s=loadStore();requireAbility('bank.import',$s);enforceCompanyAccess($s,$companyId);$fh=fopen('php://temp','r+');fwrite($fh,$csv);rewind($fh);$head=fgetcsv($fh);if(!$head)throw new InvalidArgumentException('CSV kosong.');$map=array_flip(array_map(fn($x)=>strtolower(trim((string)$x)),$head));foreach(['date','description','amount','direction'] as $k)if(!isset($map[$k]))throw new InvalidArgumentException('CSV wajib memiliki kolom date,description,amount,direction.');$rows=[];while(($r=fgetcsv($fh))!==false){$date=trim($r[$map['date']]??'');$desc=trim($r[$map['description']]??'');$amount=(float)str_replace([',',' '],['',''],$r[$map['amount']]??0);$dir=strtolower(trim($r[$map['direction']]??''));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$desc===''||$amount<=0||!in_array($dir,['in','out'],true))continue;$rows[]=['company_id'=>$companyId,'date'=>$date,'description'=>$desc,'amount'=>$amount,'direction'=>$dir,'status'=>'unmatched','journal_id'=>null,'external_ref'=>'CSV-'.substr(hash('sha256',$date.'|'.$desc.'|'.$amount.'|'.$dir),0,20)];}fclose($fh);if(!$rows)throw new RuntimeException('Tidak ada baris bank valid yang dapat diimpor.');$imported=[];$skipped=0;if($config['demo_mode']){$existing=[];foreach($s['bank_feed']??[] as $x)$existing[(int)$x['company_id'].'|'.($x['external_ref']??'')]=1;$next=(int)($s['meta']['next_bank_id']??1);foreach($rows as $r){$key=$companyId.'|'.$r['external_ref'];if(isset($existing[$key])){$skipped++;continue;}$r['id']=$next++;$s['bank_feed'][]=$r;$imported[]=$r;$existing[$key]=1;}$s['meta']['next_bank_id']=$next;saveStore($s);writeAudit('bank.csv_imported',['company_id'=>$companyId,'rows'=>count($imported),'skipped'=>$skipped]);return ['count'=>count($imported),'skipped'=>$skipped,'rows'=>$imported];}$pdo=db();$pdo->beginTransaction();try{$st=$pdo->prepare("INSERT IGNORE INTO bank_feed(company_id,txn_date,description,amount,direction,status,external_ref) VALUES(?,?,?,?,?,'unmatched',?)");foreach($rows as $r){$st->execute([$companyId,$r['date'],$r['description'],$r['amount'],$r['direction'],$r['external_ref']]);if($st->rowCount()===1)$imported[]=$r;else$skipped++;}$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}writeAudit('bank.csv_imported',['company_id'=>$companyId,'rows'=>count($imported),'skipped'=>$skipped]);return ['count'=>count($imported),'skipped'=>$skipped,'rows'=>$imported];}

function createCompany(array $input): array { global $config;$s=loadStore();requireAbility('company.manage',$s);$code=strtoupper(trim((string)($input['code']??'')));$name=trim((string)($input['name']??''));$type=trim((string)($input['business_type']??''));if(!preg_match('/^[A-Z0-9_-]{2,20}$/',$code)||textLength($name)<3||textLength($type)<2)throw new InvalidArgumentException('Kode, nama, atau jenis usaha tidak valid.');foreach($s['companies']??[] as $c)if(strtoupper((string)$c['code'])===$code)throw new RuntimeException('Kode badan usaha sudah digunakan.');if($config['demo_mode']){$id=(int)($s['meta']['next_company_id']??(max(array_column($s['companies'],'id'))+1));$row=['id'=>$id,'code'=>$code,'name'=>$name,'type'=>$type,'color'=>'violet'];$s['companies'][]=$row;$s['meta']['next_company_id']=$id+1;saveStore($s);writeAudit('company.created',['id'=>$id,'code'=>$code]);return $row;}$pdo=db();$st=$pdo->prepare("INSERT INTO companies(code,name,business_type,is_active) VALUES(?,?,?,1)");$st->execute([$code,$name,$type]);$row=['id'=>(int)$pdo->lastInsertId(),'code'=>$code,'name'=>$name,'type'=>$type];writeAudit('company.created',['id'=>$row['id'],'code'=>$code]);return $row; }
function createUserAccount(array $input): array { global $config;$s=loadStore();requireAbility('user.manage',$s);$name=trim((string)($input['name']??''));$email=strtolower(trim((string)($input['email']??'')));$role=(string)($input['role']??'viewer');$company=($input['company_id']??'')!==''?(int)$input['company_id']:null;$password=(string)($input['password']??'');$allowed=['group_owner','group_finance','entity_admin','auditor','viewer'];if(textLength($name)<3||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($role,$allowed,true)||strlen($password)<12)throw new InvalidArgumentException('Data user tidak valid atau password kurang dari 12 karakter.');if($role==='entity_admin'&&!$company)throw new InvalidArgumentException('Entity Admin wajib memiliki badan usaha.');if($company&&!isset(companyMap($s)[$company]))throw new InvalidArgumentException('Badan usaha user tidak ditemukan.');foreach($s['users']??[] as $u)if(strtolower((string)$u['email'])===$email)throw new RuntimeException('Email user sudah digunakan.');$hash=password_hash($password,PASSWORD_DEFAULT);if($config['demo_mode']){$id=(int)($s['meta']['next_user_id']??(max(array_column($s['users'],'id'))+1));$row=['id'=>$id,'name'=>$name,'email'=>$email,'role'=>$role,'company_id'=>$company,'active'=>1,'password_hash'=>$hash];$s['users'][]=$row;$s['meta']['next_user_id']=$id+1;saveStore($s);writeAudit('user.created',['id'=>$id,'role'=>$role]);unset($row['password_hash']);return $row;}$pdo=db();$st=$pdo->prepare("INSERT INTO users(name,email,password_hash,role,company_id,is_active) VALUES(?,?,?,?,?,1)");$st->execute([$name,$email,$hash,$role,$company]);$row=['id'=>(int)$pdo->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>$role,'company_id'=>$company];writeAudit('user.created',['id'=>$row['id'],'role'=>$role]);return $row; }
function createBudget(array $input): array { global $config;$s=loadStore();requireAbility('budget.manage',$s);$company=(int)($input['company_id']??0);$year=(int)($input['year']??date('Y'));$period=(int)($input['period']??date('n'));$amount=(float)($input['amount']??0);$account=(int)($input['account_id']??0);if(!$company||$year<2000||$period<1||$period>12||$amount<0||!$account)throw new InvalidArgumentException('Data budget tidak valid.');enforceCompanyAccess($s,$company);$am=accountMap($s);$a=$am[$account]??null;if(!$a)throw new InvalidArgumentException('Akun budget tidak ditemukan.');$owner=(int)($a['company_id']??0);if($owner!==0&&$owner!==$company)throw new RuntimeException('Akun budget bukan milik badan usaha yang dipilih.');if($config['demo_mode']){$found=false;foreach($s['budgets'] as &$b){if((int)$b['company_id']===$company&&(int)($b['fiscal_year']??$year)===$year&&(int)($b['period']??$period)===$period){$b['budget']=$amount;$b['fiscal_year']=$year;$b['period']=$period;$b['account_id']=$account;$found=true;$row=$b;break;}}unset($b);if(!$found){$row=['company_id'=>$company,'fiscal_year'=>$year,'period'=>$period,'account_id'=>$account,'budget'=>$amount];$s['budgets'][]=$row;}saveStore($s);writeAudit('budget.saved',['company_id'=>$company,'year'=>$year,'period'=>$period,'amount'=>$amount]);return $row;}$pdo=db();$st=$pdo->prepare("INSERT INTO budgets(company_id,fiscal_year,period,account_id,amount,scenario) VALUES(?,?,?,?,?,'budget') ON DUPLICATE KEY UPDATE amount=VALUES(amount)");$st->execute([$company,$year,$period,$account,$amount]);writeAudit('budget.saved',['company_id'=>$company,'year'=>$year,'period'=>$period,'amount'=>$amount]);return ['company_id'=>$company,'year'=>$year,'period'=>$period,'account_id'=>$account,'amount'=>$amount]; }
function createAsset(array $input): array { global $config;$s=loadStore();requireAbility('asset.manage',$s);$company=(int)($input['company_id']??0);$name=trim((string)($input['name']??''));$category=trim((string)($input['category']??''));$date=(string)($input['acquisition_date']??date('Y-m-d'));$cost=(float)($input['cost']??0);$life=(int)($input['useful_life_months']??0);$residual=(float)($input['residual_value']??0);if(!$company||textLength($name)<2||textLength($category)<2||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$cost<0||$life<=0||$residual<0||$residual>$cost)throw new InvalidArgumentException('Data aset tidak valid.');enforceCompanyAccess($s,$company);if($config['demo_mode']){$id=(int)($s['meta']['next_asset_id']??(count($s['assets'])+1));$acq=new DateTimeImmutable($date);$today=new DateTimeImmutable(date('Y-m-d'));$months=0;if($acq<=$today){$diff=$acq->diff($today);$months=max(0,min($life,$diff->y*12+$diff->m));}$book=max($residual,$cost-(($cost-$residual)/$life*$months));$row=['id'=>$id,'company_id'=>$company,'name'=>$name,'category'=>$category,'acquisition_date'=>$date,'cost'=>$cost,'book'=>$book,'useful_life_months'=>$life,'residual_value'=>$residual];$s['assets'][]=$row;$s['meta']['next_asset_id']=$id+1;saveStore($s);writeAudit('asset.created',['id'=>$id,'company_id'=>$company]);return $row;}$pdo=db();$code='AST-'.strtoupper(bin2hex(random_bytes(4)));$st=$pdo->prepare("INSERT INTO fixed_assets(company_id,asset_code,name,category,acquisition_date,acquisition_cost,useful_life_months,residual_value,status) VALUES(?,?,?,?,?,?,?,?, 'active')");$st->execute([$company,$code,$name,$category,$date,$cost,$life,$residual]);$row=['id'=>(int)$pdo->lastInsertId(),'company_id'=>$company,'name'=>$name,'category'=>$category,'cost'=>$cost,'book'=>$cost];writeAudit('asset.created',['id'=>$row['id'],'company_id'=>$company]);return $row; }
