function createBranch(array $input): array {
    global $config;
    $s=loadStore();requireAbility('company.manage',$s);
    $company=(int)($input['company_id']??0);$code=strtoupper(trim((string)($input['code']??'')));$name=trim((string)($input['name']??''));$timezone=trim((string)($input['timezone']??$config['timezone']));
    if(!$company||!preg_match('/^[A-Z0-9_-]{2,30}$/',$code)||textLength($name)<2||textLength($timezone)<3)throw new InvalidArgumentException('Data cabang tidak valid.');
    enforceCompanyAccess($s,$company);
