        foreach($s['branches']??[] as $b)if((int)$b['company_id']===$company&&strtoupper((string)$b['code'])===$code)throw new RuntimeException('Kode cabang sudah digunakan.');
        $ids=array_map('intval',array_column($s['branches']??[],'id'));$id=($ids?max($ids):0)+1;
        $row=['id'=>$id,'company_id'=>$company,'code'=>$code,'name'=>$name,'timezone'=>$timezone,'active'=>1];$s['branches'][]=$row;saveStore($s);writeAudit('branch.created',['id'=>$id,'company_id'=>$company]);return$row;
    }
    $pdo=db();$st=$pdo->prepare("INSERT INTO branches(company_id,code,name,timezone,is_active) VALUES(?,?,?,?,1) ON DUPLICATE KEY UPDATE name=VALUES(name),timezone=VALUES(timezone),is_active=1");$st->execute([$company,$code,$name,$timezone]);
