        $row=['id'=>$id,'company_id'=>$company,'branch_id'=>$branch,'code'=>$code,'name'=>$name,'cost_center_code'=>$cost?:null,'profit_center_code'=>$profit?:null,'active'=>1];$s['departments'][]=$row;saveStore($s);writeAudit('department.created',['id'=>$id,'company_id'=>$company,'branch_id'=>$branch]);return$row;
