    writeAudit('department.created',['id'=>$id,'company_id'=>$company,'branch_id'=>$branch]);return['id'=>$id,'company_id'=>$company,'branch_id'=>$branch,'code'=>$code,'name'=>$name,'cost_center_code'=>$cost?:null,'profit_center_code'=>$profit?:null,'active'=>1];
